ALTER TABLE public.featured_packages ADD COLUMN IF NOT EXISTS max_vagas integer NOT NULL DEFAULT 3, ADD COLUMN IF NOT EXISTS formato_imagem text, ADD COLUMN IF NOT EXISTS exclusivo boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.featured_packages.max_vagas IS 'Vagas simultâneas do espaço (por categoria quando escopo = home_categoria). Exclusivo ocupa todas.';
ALTER TABLE public.featured_packages DROP CONSTRAINT IF EXISTS featured_packages_escopo_check;
ALTER TABLE public.featured_packages ADD CONSTRAINT featured_packages_escopo_check CHECK (escopo IN ('categoria','home','cidade','home_hero','home_story','home_form','home_categoria'));
UPDATE public.featured_packages SET max_vagas = 3, formato_imagem = '2400x1600' WHERE escopo = 'home' AND formato_imagem IS NULL;
ALTER TABLE public.featured_purchases ADD COLUMN IF NOT EXISTS package_id uuid REFERENCES public.featured_packages(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS legenda text, ADD COLUMN IF NOT EXISTS link_destino text, ADD COLUMN IF NOT EXISTS exclusivo boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS imagem_status text NOT NULL DEFAULT 'pendente', ADD COLUMN IF NOT EXISTS imagem_motivo_recusa text, ADD COLUMN IF NOT EXISTS foco_desktop text NOT NULL DEFAULT '50% 50%', ADD COLUMN IF NOT EXISTS foco_mobile text NOT NULL DEFAULT '50% 50%';
ALTER TABLE public.featured_purchases DROP CONSTRAINT IF EXISTS featured_purchases_escopo_check;
ALTER TABLE public.featured_purchases ADD CONSTRAINT featured_purchases_escopo_check CHECK (escopo IN ('categoria','home','cidade','home_hero','home_story','home_form','home_categoria'));
DO $$ BEGIN ALTER TABLE public.featured_purchases ADD CONSTRAINT featured_purchases_imagem_status_chk CHECK (imagem_status IN ('pendente','aprovada','recusada')); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
UPDATE public.featured_purchases SET imagem_status = 'aprovada' WHERE status IN ('ativo','pago') AND imagem_status = 'pendente';
CREATE INDEX IF NOT EXISTS featured_purchases_vigencia_idx ON public.featured_purchases (escopo, status, fim);
ALTER TABLE public.secoes_home ADD COLUMN IF NOT EXISTS categoria_id uuid REFERENCES public.categories(id) ON DELETE CASCADE, ADD COLUMN IF NOT EXISTS link_destino text, ADD COLUMN IF NOT EXISTS foco_desktop text NOT NULL DEFAULT '50% 50%', ADD COLUMN IF NOT EXISTS foco_mobile text NOT NULL DEFAULT '50% 50%';
CREATE TABLE IF NOT EXISTS public.featured_events (id bigserial PRIMARY KEY, purchase_id uuid NOT NULL REFERENCES public.featured_purchases(id) ON DELETE CASCADE, tipo text NOT NULL CHECK (tipo IN ('impressao','clique')), sessao text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.featured_events TO authenticated;
GRANT ALL ON public.featured_events TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.featured_events_id_seq TO service_role;
ALTER TABLE public.featured_events ENABLE ROW LEVEL SECURITY;
CREATE INDEX IF NOT EXISTS featured_events_purchase_idx ON public.featured_events (purchase_id, tipo, created_at);
DROP POLICY IF EXISTS "Fornecedor vê eventos dos próprios destaques" ON public.featured_events;
CREATE POLICY "Fornecedor vê eventos dos próprios destaques" ON public.featured_events FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.featured_purchases fp JOIN public.suppliers s ON s.id = fp.supplier_id WHERE fp.id = purchase_id AND s.user_id = auth.uid()) OR public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE OR REPLACE FUNCTION public.home_destaques_ativos() RETURNS TABLE (id uuid, escopo text, supplier_id uuid, supplier_nome text, categoria_id uuid, categoria_nome text, categoria_slug text, imagem_url text, legenda text, link_destino text, exclusivo boolean, foco_desktop text, foco_mobile text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT fp.id, CASE WHEN fp.escopo = 'home' THEN 'home_hero' ELSE fp.escopo END, fp.supplier_id, s.company_name, COALESCE(fp.escopo_categoria_id, s.category_id), c.name, c.slug, fp.imagem_url, fp.legenda, fp.link_destino, fp.exclusivo, fp.foco_desktop, fp.foco_mobile FROM public.featured_purchases fp JOIN public.suppliers s ON s.id = fp.supplier_id LEFT JOIN public.categories c ON c.id = COALESCE(fp.escopo_categoria_id, s.category_id) WHERE fp.escopo IN ('home','home_hero','home_story','home_form','home_categoria') AND fp.status IN ('ativo','pago') AND fp.imagem_status = 'aprovada' AND fp.imagem_url IS NOT NULL AND fp.inicio <= now() AND fp.fim >= now() AND s.status = 'approved' ORDER BY fp.inicio; $$;
REVOKE ALL ON FUNCTION public.home_destaques_ativos() FROM public;
GRANT EXECUTE ON FUNCTION public.home_destaques_ativos() TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.registrar_evento_destaque(p_purchase uuid, p_tipo text, p_sessao text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF p_tipo NOT IN ('impressao','clique') THEN RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM public.featured_purchases WHERE id = p_purchase AND status IN ('ativo','pago') AND inicio <= now() AND fim >= now()) THEN RETURN; END IF; IF p_sessao IS NOT NULL AND EXISTS (SELECT 1 FROM public.featured_events WHERE purchase_id = p_purchase AND tipo = p_tipo AND sessao = p_sessao AND created_at > now() - CASE WHEN p_tipo = 'impressao' THEN interval '30 minutes' ELSE interval '1 minute' END) THEN RETURN; END IF; INSERT INTO public.featured_events (purchase_id, tipo, sessao) VALUES (p_purchase, p_tipo, left(p_sessao, 64)); END; $$;
REVOKE ALL ON FUNCTION public.registrar_evento_destaque(uuid,text,text) FROM public;
GRANT EXECUTE ON FUNCTION public.registrar_evento_destaque(uuid,text,text) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.vagas_destaque_disponiveis(p_escopo text, p_categoria uuid DEFAULT NULL) RETURNS integer LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ DECLARE v_max integer; v_ocupadas integer; v_escopos text[]; BEGIN v_escopos := CASE WHEN p_escopo IN ('home','home_hero') THEN ARRAY['home','home_hero'] ELSE ARRAY[p_escopo] END; SELECT COALESCE(MAX(max_vagas),0) INTO v_max FROM public.featured_packages WHERE escopo = ANY(v_escopos) AND ativo; IF v_max = 0 THEN RETURN 0; END IF; SELECT COALESCE(SUM(CASE WHEN fp.exclusivo THEN v_max ELSE 1 END),0) INTO v_ocupadas FROM public.featured_purchases fp WHERE fp.escopo = ANY(v_escopos) AND (p_escopo <> 'home_categoria' OR fp.escopo_categoria_id = p_categoria) AND fp.imagem_status <> 'recusada' AND ((fp.status IN ('ativo','pago') AND fp.fim >= now()) OR (fp.status = 'pendente' AND fp.created_at > now() - interval '30 minutes')); RETURN GREATEST(v_max - v_ocupadas,0); END; $$;
GRANT EXECUTE ON FUNCTION public.vagas_destaque_disponiveis(text,uuid) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.featured_purchases_checa_vaga() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_livres integer; v_max integer; v_pac record; BEGIN IF NOT (public.has_role(auth.uid(),'admin'::public.app_role) OR auth.role() = 'service_role') THEN NEW.status := 'pendente'; NEW.imagem_status := 'pendente'; NEW.imagem_motivo_recusa := NULL; IF NEW.package_id IS NOT NULL THEN SELECT valor,dias,escopo,exclusivo INTO v_pac FROM public.featured_packages WHERE id = NEW.package_id AND ativo; IF NOT FOUND THEN RAISE EXCEPTION 'Pacote de destaque indisponível.' USING ERRCODE = 'P0001'; END IF; NEW.valor := v_pac.valor; NEW.dias := v_pac.dias; NEW.escopo := v_pac.escopo; NEW.exclusivo := v_pac.exclusivo; END IF; END IF; IF NEW.escopo NOT IN ('home','home_hero','home_story','home_form','home_categoria') THEN RETURN NEW; END IF; IF NEW.escopo = 'home_categoria' AND NEW.escopo_categoria_id IS NULL THEN SELECT category_id INTO NEW.escopo_categoria_id FROM public.suppliers WHERE id = NEW.supplier_id; END IF; v_livres := public.vagas_destaque_disponiveis(NEW.escopo,NEW.escopo_categoria_id); IF NEW.exclusivo THEN SELECT COALESCE(MAX(max_vagas),0) INTO v_max FROM public.featured_packages WHERE escopo = NEW.escopo AND ativo; IF v_livres < v_max THEN RAISE EXCEPTION 'Destaque exclusivo indisponível: já existem destaques ativos neste espaço.' USING ERRCODE = 'P0001'; END IF; ELSIF v_livres < 1 THEN RAISE EXCEPTION 'Sem vagas neste destaque no momento. Entre na lista de espera.' USING ERRCODE = 'P0001'; END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS featured_purchases_checa_vaga_trg ON public.featured_purchases;
CREATE TRIGGER featured_purchases_checa_vaga_trg BEFORE INSERT ON public.featured_purchases FOR EACH ROW EXECUTE FUNCTION public.featured_purchases_checa_vaga();
ALTER TABLE public.platform_reviews ADD COLUMN IF NOT EXISTS autor_tipo text NOT NULL DEFAULT 'casal', ADD COLUMN IF NOT EXISTS autor_detalhe text;
DO $$ BEGIN ALTER TABLE public.platform_reviews ADD CONSTRAINT platform_reviews_autor_tipo_chk CHECK (autor_tipo IN ('casal','fornecedor')); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
COMMENT ON COLUMN public.platform_reviews.autor_detalhe IS 'Linha de contexto do card. Ex.: "Casaram em mai/2026 · Buffet" ou "Fotografia · Belo Horizonte".';
CREATE OR REPLACE FUNCTION public.featured_purchases_reanalisa_imagem() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF public.has_role(auth.uid(),'admin'::public.app_role) OR auth.role() = 'service_role' THEN RETURN NEW; END IF; NEW.imagem_status := OLD.imagem_status; NEW.imagem_motivo_recusa := OLD.imagem_motivo_recusa; IF NEW.imagem_url IS DISTINCT FROM OLD.imagem_url THEN NEW.imagem_status := 'pendente'; NEW.imagem_motivo_recusa := NULL; END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS featured_purchases_reanalisa_imagem_trg ON public.featured_purchases;
CREATE TRIGGER featured_purchases_reanalisa_imagem_trg BEFORE UPDATE ON public.featured_purchases FOR EACH ROW EXECUTE FUNCTION public.featured_purchases_reanalisa_imagem();